using Microsoft.EntityFrameworkCore;
namespace SimrsKhanza.Data;

public sealed class RujukanKeluarRow { public string NoRujuk {get;set;}=""; public string NoRawat {get;set;}=""; public string NoRm {get;set;}=""; public string Pasien {get;set;}=""; public DateTime? Tanggal {get;set;} public string? Tujuan {get;set;} public string? Diagnosa {get;set;} public string? Dokter {get;set;} public string? Keterangan {get;set;} }
public sealed class RujukanMasukRow { public string NoRawat {get;set;}=""; public string NoRm {get;set;}=""; public string Pasien {get;set;}=""; public DateTime? Tanggal {get;set;} public string? Perujuk {get;set;} public string Alamat {get;set;}=""; public string NoRujuk {get;set;}=""; public string? DokterPerujuk {get;set;} public string? Keterangan {get;set;} }
public sealed class PemberianObatRow { public DateTime Tanggal {get;set;} public TimeSpan Jam {get;set;} public string NoRawat {get;set;}=""; public string NoRm {get;set;}=""; public string Pasien {get;set;}=""; public string KodeObat {get;set;}=""; public string Obat {get;set;}=""; public double Jumlah {get;set;} public double Total {get;set;} public string? Status {get;set;} public string Batch {get;set;}=""; public string Faktur {get;set;}=""; }
public sealed class RujukanObatRepository(SimrsKhanzaDbContext db)
{
    public Task<List<RujukanKeluarRow>> KeluarAsync(DateTime a,DateTime b,string q)=>db.Database.SqlQueryRaw<RujukanKeluarRow>(@"select x.no_rujuk NoRujuk,coalesce(x.no_rawat,'') NoRawat,r.no_rkm_medis NoRm,p.nm_pasien Pasien,x.tgl_rujuk Tanggal,x.rujuk_ke Tujuan,x.keterangan_diagnosa Diagnosa,d.nm_dokter Dokter,x.keterangan Keterangan from rujuk x join reg_periksa r on r.no_rawat=x.no_rawat join pasien p on p.no_rkm_medis=r.no_rkm_medis left join dokter d on d.kd_dokter=x.kd_dokter where x.tgl_rujuk between {0} and {1} and (x.no_rujuk like {2} or x.no_rawat like {2} or p.nm_pasien like {2} or r.no_rkm_medis like {2} or x.rujuk_ke like {2}) order by x.tgl_rujuk desc,x.jam desc",a.Date,b.Date,"%"+q+"%").ToListAsync();
    public Task<List<RujukanMasukRow>> MasukAsync(DateTime a,DateTime b,string q)=>db.Database.SqlQueryRaw<RujukanMasukRow>(@"select x.no_rawat NoRawat,r.no_rkm_medis NoRm,p.nm_pasien Pasien,r.tgl_registrasi Tanggal,x.perujuk Perujuk,x.alamat Alamat,x.no_rujuk NoRujuk,x.dokter_perujuk DokterPerujuk,x.keterangan Keterangan from rujuk_masuk x join reg_periksa r on r.no_rawat=x.no_rawat join pasien p on p.no_rkm_medis=r.no_rkm_medis where r.tgl_registrasi between {0} and {1} and (x.no_rawat like {2} or r.no_rkm_medis like {2} or p.nm_pasien like {2} or x.perujuk like {2} or x.no_rujuk like {2}) order by r.tgl_registrasi desc",a.Date,b.Date,"%"+q+"%").ToListAsync();
    public Task<List<PemberianObatRow>> ObatAsync(DateTime a,DateTime b,string q)=>db.Database.SqlQueryRaw<PemberianObatRow>(@"select x.tgl_perawatan Tanggal,x.jam Jam,x.no_rawat NoRawat,r.no_rkm_medis NoRm,p.nm_pasien Pasien,x.kode_brng KodeObat,d.nama_brng Obat,x.jml Jumlah,x.total Total,x.status Status,x.no_batch Batch,x.no_faktur Faktur from detail_pemberian_obat x join reg_periksa r on r.no_rawat=x.no_rawat join pasien p on p.no_rkm_medis=r.no_rkm_medis join databarang d on d.kode_brng=x.kode_brng where x.tgl_perawatan between {0} and {1} and (x.no_rawat like {2} or r.no_rkm_medis like {2} or p.nm_pasien like {2} or d.nama_brng like {2} or x.kode_brng like {2}) order by x.tgl_perawatan desc,x.jam desc",a.Date,b.Date,"%"+q+"%").ToListAsync();
}
